export function readCatalog(query) {
  const result = query({ query: 'SELECT catalog_snapshot', readOnly: true });
  if (result.principal !== 'catalog_owner' || !result.readOnlyTransaction) throw new Error('catalog_assurance_failed');
  return result.objectCount;
}

