import { cp, mkdtemp, readFile, rm } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { spawnSync } from 'node:child_process';
const source = resolve('.');
const scratch = await mkdtemp(join(tmpdir(), 'clean-prepare-'));
try {
  const project = join(scratch, 'project');
  await cp(source, project, {recursive: true, filter: p => !/(^|\/)(node_modules|out|\.git)(\/|$)/.test(p.slice(source.length))});
  const job = JSON.parse(await readFile(join(project, '.ci/prepare-job.json'), 'utf8'));
  for (const command of job.commands) {
    console.log(JSON.stringify({cwd: project, command, initialState: 'clean checkout'}));
    const result = spawnSync(command[0], command.slice(1), {cwd: project, encoding:'utf8', env: {...process.env, npm_config_cache: join(scratch,'cache')}});
    process.stdout.write(result.stdout ?? '');
    process.stderr.write(result.stderr ?? '');
    if (result.status !== 0) { process.exitCode = result.status ?? 1; break; }
  }
} finally { await rm(scratch, {recursive:true, force:true}); }

