import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
test('prepare writes candidate metadata in developer directory', () => {
 const run = spawnSync(process.execPath, ['scripts/prepare.mjs'], {encoding:'utf8'});
 assert.equal(run.status, 0, run.stderr);
 assert.deepEqual(JSON.parse(readFileSync('out/prepared.json')), {candidate:'candidate-19', formatVersion:1});
});

